import{_ as s,O as a,o as i,c as r,a as o,i as n,f as c}from"./chunks/framework.fmIt2z2h.js";const g=JSON.parse('{"title":"D.05　信息、表示、数学与物理借用","description":"","frontmatter":{"title":"D.05　信息、表示、数学与物理借用","xkChars":711,"xkLessons":{"D.05":{"title":"D.05　信息、表示、数学与物理借用","lead":"一份只保留总数的表，可能足够回答总量，却不能回答分配。抽象并非一律不好；关键是它保留了当前问题所需的区别，且没有把这种充分性偷偷扩大到未来动态、干预或人的价值判断。","explanation":["原文定位：第4593—4608行；原文锚点 section-d-05；短引文：‘源信息减少不必导致当前任务失败。’。本题源切片逐字另附于source-slice.md，讲解与原文分开。","表示要按五个维度分别评价：源状态能否恢复，指定任务能否完成，计算成本是否承受得起，未来动态是否闭合，以及允许干预后是否仍充分。无损恢复最强细节并不总是当前任务所需；只问总量可以不保留每项身份。但任务够用不代表未来所有问题都够用，目标一变、时间推进或干预改变通道，原先被合并的区别可能重新重要。","设源域X、表示f:X→Z、问题q:X→Y。存在答案函数g使q=g∘f，当且仅当同一表示的源状态具有相同答案，也就是q在每个f原像集合上恒定。必要性：f(x)=f(x′)时，q(x)=g(f(x))=g(f(x′))=q(x′)。充分性：对可达表示z∈f(X)，把g(z)定义为任一对应x的q(x)；由于同原像恒定，定义不依赖选择。这里只需在实际可达表示上定义；若要求在整个Z扩展，还须相应的非空值域等普通集合前提。","这个判据给抽象正面成立条件，不只是提醒有信息损失。例如保留(a+b)足以回答a+b，即使不能恢复a和b；如果问题改为a是否大于b，原像中答案可不同，充分性失败。失败后可补入真正影响目标的隐藏份额，不必无止境恢复所有细节。补测和维护本身有费用、隐私和理解负担，表示越细并非自动更好。","允许干预后是否充分是额外问题。若原目标只是总库存a+b+c，存一个总量即可；若要移除a份后报剩余总量，则同总量下a不同会产生不同结果。加入a便可用总量减a回答，而b、c各自细节仍不必恢复。这说明精化应针对目标和允许操作，不能因一次闭合失败就宣布所有抽象均无效。","单位换算、会计恒等、经验转换率与价值权重属于不同根据。单位换算在定义及单位对应下改写同一量；会计恒等根据登记边界核平衡；经验转换率须由相应材料支持且会随条件变；价值权重体现规范取舍。不能把一个领域中的单位换算式当作不同人的痛苦、注意力和责任可精确通约的证明。","物质或能量守恒须正确边界与量纲，社会领域共用“负荷”“势场”“熵”等词没有自动获得守恒律。真实技术改善可以消除重复劳动或减少伤害，从而降低实际成本，不必强行解释为相同成本一定转移到看不见的地方。若怀疑成本转移应找具体承担者和通道，不能用无法反驳的隐藏负担保存比喻。","哥德尔不完备性与可计算性结果都依赖特定形式系统和问题类别，不能推出每个有限任务无法判断。一个有限且完整、可取得的表可以逐项查；一般无限域中，答案作为数学函数存在不保证有总停止的算法。即使有算法，也可能超预算；即使预算可承受，资料可能来不及取得；即使资料到手，使用者仍可能操作错误。这些是分别需要核验的层次，不能用信息未丢失一口气包办。","模型简约不能只数最终参数。搜索过多少表示、如何调参、花费多少资源、是否改变目标，都影响比较。一个最后只剩两参数但经历大量隐性搜索的模型，不自动比有更多参数却预先固定的方法更少过拟合或更低成本。正式比较应保留选择过程和强对照，不以数学或物理名声代替目标域的经验前提。","多次转换必须保持同一个最终问题q。若第一步f已充分，第二步h须在实际可达的中间表示f(X)上保留原答案所需区别，才可能用k使q=k∘h∘f。第一步回答总量、第二步回答排序各自成功，不代表拼接后还能回答原先的总量。局部任务更换时要公开，不把两个不同任务的局部正确冒充整链充分。","八个研究入口覆盖Shannon信息论、压缩转义、熵与社会秩序类比、守恒势场借用、不完备与可计算性、粗粒化和闭合、信息或量子宇宙类比的历史退场、模型选择与表达能力。本节要求保留这些题目的具体假设与边界，不据目录宣称全部理论已被采纳或证明。最强反方觉得任何压缩都危险；上述原像判据说明有损表示可对指定任务严格充分。另一反方认为任务足够就不用再检查，则忽略了算法、时间、资料与实际使用的独立条件。"],"distinctions":[{"leftTitle":"源状态可恢复","leftText":"能重建原状态的全部所指细节。","rightTitle":"任务充分","rightText":"只需保留q所需区别，可有其他信息损失。"},{"leftTitle":"函数存在","leftText":"数学上q可经表示分解。","rightTitle":"有效可计算","rightText":"还需算法和终止等条件，不能由存在直接推出。"},{"leftTitle":"单位与会计恒等","leftText":"依赖定义、量纲和登记边界。","rightTitle":"经验率与价值权重","rightText":"分别需经验材料或公开规范理由。"},{"leftTitle":"当前充分","leftText":"对当前问题足够。","rightTitle":"动态干预充分","rightText":"后续变化和允许操作也保留所需区别，须额外检查。"},{"leftTitle":"最终模型简短","leftText":"参数或表达较少。","rightTitle":"全部选择过程简约","rightText":"还包括搜索、调参、资源和目标变化。"}],"boundaries":["原像恒定判据首先在f(X)上构造答案函数，现实可计算性及数据取得另外核。","社会负担不因同名获得物理守恒律，减少成本是真实可能。","有限完整表与一般无限问题不同，不用不完备性否定所有有限判断。","多步转换不能更换最终问题后冒称整链仍充分。","教学形式例无实测数据；本讲未对用户文件进行编码转换或删除信息。"],"questions":["为什么充分性证明只先定义g在f(X)上？","总量10为何不能回答移除a后的量？","物理守恒可否直接用于痛苦总量？","第二步回答了新问题且完全正确，是否保住旧问题？"],"diagramPath":"/reading-assets/S-D-05/figures/section-d-05.png","caseLinks":[{"title":"真实标准中的限制：Unicode兼容规范化会抹去某些区别","href":"https://www.unicode.org/reports/tr15/tr15-58.html"}],"caseNotes":[{"title":"真实标准中的限制：Unicode兼容规范化会抹去某些区别","text":"Unicode UAX15第58修订版标注Unicode18.0.0、2026年8月12日。§1.1说明兼容等价可能保留在特定语境有意义的视觉或语义区别；§1.2明确警告NFKC/NFKD不能盲目应用任意文本，因为它们会去掉格式差异，可能影响往返转换及文本语义。这是实际编码标准对转换用途的限定。","sourceLabel":"Unicode Standard Annex15，Revision58固定版本","sourceUrl":"https://www.unicode.org/reports/tr15/tr15-58.html","sourceLocator":"版本表；§1.1关于compatibility equivalence的后续两段；§1.2 Normalization Forms KC and KD must not…及下一段","boundary":"只核标准的定义和用途警告，不声称所有规范化有害或每种语义任务失效，不把字符转换等同人的信息与价值。","href":"https://www.unicode.org/reports/tr15/tr15-58.html"}],"sourceRefs":[{"section":"D.05","start_line":4593,"end_line":4608,"startLine":4593,"endLine":4608}],"outputId":"section-d-05","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["固定最终问题q、源域、表示f和允许操作，分开五个充分性维度。","用同一f原像中q是否恒定，公开证明或反驳答案函数存在。","动态或干预失配时只补真正需要的区别，并计量隐私测量维护理解成本。","多次转换保持同一最终问题，在实际可达中间域核后续充分性。","分别检查函数存在、有效算法、预算、及时资料与使用正确，不将数学声望或守恒词语外推成社会事实。"],"teachingExamples":[{"title":"数学教学构造：总量足够，分配不足","text":"在有限域X={(1,3),(2,2),(3,1)}，f(a,b)=a+b恒为4。若q=a+b，则g(4)=4足够；若q′判断a>b，三态答案依次假、假、真，同一原像中不恒定，因此任何只看4的答案函数都不能同时正确。","assumptions":"有限域与问题明确，无测量噪声。","boundary":"不把此有限判据当作所有实际压缩任务的效果保证。"},{"title":"数学教学构造：只补需要的隐藏份额","text":"状态x=(a,b,c)，原表示总量T=a+b+c。比较(2,3,5)与(4,1,5)，总量均10；允许移除a后，剩余分别8与6，原表示不足。加入a得到(T,a)后，统一用T−a回答，仍不需分别恢复b和c。","assumptions":"库存为非负数，移除a的操作定义明确、无其他动力与成本。","boundary":"实际测量、权限和操作代价未由形式例证明。"},{"title":"数学教学构造：两步必须保留同一问题","text":"令X={0,1,2,3}，最终问题q为奇偶，第一步f(x)=x mod2足够。若第二步h把0和1都映为同一符号，最终表示无法区分奇偶；h可能完成“是否属于二元集合”这一局部任务，却没有保留原q。","assumptions":"完全有限函数，可穷举。","boundary":"不同局部任务各自完成不能补回已经合并的最终答案区别。"}],"counterexamples":[{"identity":"constructed_boundary","text":"只要丢了原始细节，任何任务都不可能完成。","effect":"原像恒定时，指定任务仍可严格充分。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"社会存在负荷，所以任何减负必等量转移给别人。","effect":"没有跨域守恒证明，技术或流程改善可真实消除重复成本。","sourceIds":["theory"]},{"identity":"source_counterexample","text":"存在答案函数，因此总有及时、低成本且正确使用的算法。","effect":"函数、算法、预算、资料和实际使用分别承担条件。","sourceIds":["theory"]}],"questionAnswers":[{"question":"为什么充分性证明只先定义g在f(X)上？","answer":"只有可达表示对应实际源状态；无需为不出现的中间值虚造任务条件。","basis":"本节原文及上述公开推导"},{"question":"总量10为何不能回答移除a后的量？","answer":"同总量对应不同a，操作后的目标在原像中不恒定；补a即可。","basis":"本节原文及上述公开推导"},{"question":"物理守恒可否直接用于痛苦总量？","answer":"不行，须有正确对象、量纲、边界及桥接，不能由共享词语推出。","basis":"本节原文及上述公开推导"},{"question":"第二步回答了新问题且完全正确，是否保住旧问题？","answer":"不一定，应检查其在可达中间表示上是否仍区分旧q的不同答案。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-D-05/figures/section-d-05.png","alt":"固定问题q与表示f，同一原像答案一致，即 q(x)=g(f(x))；五维分别核，恢复／任务／成本，动态／干预；失配后定向补充，只加所需隐藏份额，计入隐私维护成本；多步保留同一q，核实际可达中间域；函数≠算法≠预算，资料及时与使用正确，仍须分别核；物理数学借用有条件，负荷同词≠守恒，声望不替经验前提。作者依D.05绘制；形式充分性在声明域和问题下成立，不认证现实使用收益。","caption":"作者依D.05绘制；形式充分性在声明域和问题下成立，不认证现实使用收益。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。切换总量与分配问题、是否允许移除隐藏份额、第二步是否合并奇偶，显示充分性条件变化。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"真实文本转换标准体现保留何种区别取决于任务；是有限方法联系而非全领域类比验证。"},"openQuestions":["未取得05.01—05.08所指全部研究原稿，不复原量子宇宙类比的具体历史采纳与退场事件。","没有实际读者成本或多步应用效果实验。"],"taskId":"S-D-05","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第4593—4608行；每节精确范围见sourceRefs","claim_support":["D.05：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"unicode-normalization","title":"Unicode Standard Annex15: Unicode Normalization Forms","url":"https://www.unicode.org/reports/tr15/tr15-58.html","source_type":"primary","version_or_date":"Unicode18.0.0，Revision58，2026-08-12","locator":"版本表；§1.1兼容等价后续两段；§1.2 NFKC/NFKD任意文本警告及下一段","claim_support":["兼容转换可能抹去语境相关区别；不应盲目应用任意文本"],"limits":["标准用途警告不等于所有任务失败，不将字符关系直接推为社会或价值规律。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-D-05/lecture.md","sourcesPath":"/reading-assets/S-D-05/sources.json","sourceSlicePath":"/reading-assets/S-D-05/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-D-05/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-d/d-05.md","filePath":"theory/appendix-d/d-05.md"}'),d={name:"theory/appendix-d/d-05.md"};function l(p,e,u,f,h,m){const t=a("SectionLesson");return i(),r("div",null,[e[0]||(e[0]=o('<div class="theory-source"><h1 id="section-d-05" tabindex="-1"><span class="xk-num"><span class="xk-num__n">D.05</span><span class="xk-num__gap">　</span></span>信息、表示、数学与物理借用 <a class="header-anchor" href="#section-d-05" aria-label="Permalink to &quot;D.05　信息、表示、数学与物理借用 {#section-d-05}&quot;">​</a></h1><p>正文连接：§2.6、2.8；§4.6、4.8；§5；附录C。研究入口：05.01—05.08。</p><p>表示需要相对于问题评价。源状态能否恢复、指定任务能否完成、计算成本是否可承受、未来动态是否闭合，以及允许干预后是否仍充分，是五个不同维度。源信息减少不必导致当前任务失败；任务充分也不能被外推为全部未来问题充分。</p><p>形式上，存在函数g使q=g∘f，当且仅当q在f的每个原像集合上取相同值；这首先是表示充分性的判据，实际可计算性另行判断。这个判据使抽象具有正面成立条件，而不只留下损失警告。若仅一个隐藏份额影响干预后结果，可以补入该份额；不必一旦闭合失败就无止境恢复所有细节。实际采用还应计入测量、隐私、维护和理解成本。</p><p>单位换算、会计恒等、经验转换率和价值权重分别成立。能量或物质守恒须有正确边界与量纲；社会负担、痛苦、注意力和道德责任没有因共享“负荷”一词就获得守恒律。消除重复劳动、改善技术或减少伤害，可以真实降低成本，不必被解释成成本必然转移到别处。</p><p>哥德尔、不完备性与可计算性的结果依赖特定形式系统及问题类别，不能推出每个有限任务都无法判断。模型简约也不只看参数数目：整个选择过程、搜索过的表示、调参预算及目标变化都应计入比较。物理或数学成果可提供精确的桥接纪律，不能以声望代替目标域的经验前提。</p><p>多次转换必须保持同一个最终问题。若第一步已经充分，第二步仍须在实际可达的中间表示上保留最终答案所需区别；分别完成两个不同的局部任务，不能证明接续后仍回答原问题。答案函数存在、有效算法存在、预算内可算、资料及时可达和实际使用正确分别检查。有限完整表可以查表，一般无限域则不能由信息未丢失推出总停止算法。</p><p>专题定位：05.01 Shannon 信息论、信道与噪声；05.02 压缩、表示与有损转义；05.03 熵、耗散结构与社会秩序类比；05.04 守恒、势场、力与承载的借用；05.05 哥德尔、不完备性与可计算性；05.06 有效理论、尺度闭合与粗粒化；05.07 信息本体、量子与宇宙类比的历史退场；05.08 模型选择、简约与表达能力。</p></div>',1)),n(t,{section:"D.05"}),e[1]||(e[1]=c("div",{class:"theory-source"},null,-1))])}const _=s(d,[["render",l]]);export{g as __pageData,_ as default};
